import { Session } from '../sessions/session.js';
import { BaseExampleProvider } from './base_example_provider.js';
import { Example } from './example.js';
/**
 * Throws unless `examples` is a well-formed list of {@link Example}s.
 *
 * Mirrors `TypeAdapter(list[Example]).validate_python` in the adk-python
 * `ExampleTool` constructor. {@link Example} is erased at compile time, so a
 * value that reaches the SDK from untyped JavaScript or from a configuration
 * file is otherwise unchecked, and a malformed entry only fails later while the
 * few-shot instruction is rendered.
 *
 * The value is checked but not replaced, so it keeps reference identity and no
 * defensive copy is made.
 *
 * @param examples - The value to check.
 * @throws {InputValidationError} When the value is not a list of well-formed
 *   examples. The message names the path of each failing field.
 */
export declare function validateExamples(examples: unknown): asserts examples is Example[];
/**
 * Converts a list of examples to a string that can be used in a system
 * instruction.
 *
 * When `model` is undefined or contains `"gemini-2"`, function calls and
 * responses are formatted with plain triple-backtick fences. For other model
 * names the legacy `tool_code` / `tool_outputs` fences are used instead.
 *
 * @param examples - The few-shot examples to convert.
 * @param model - Optional model name used to select the function-call fence
 *   style. Defaults to the gemini-2 style when omitted.
 * @returns A formatted string wrapped in `<EXAMPLES>…</EXAMPLES>` tags,
 *   suitable for inclusion in a system instruction.
 */
export declare function convertExamplesToText(examples: Example[], model?: string): string;
/**
 * Gets the latest message from the user.
 *
 * @param session - The session to inspect.
 * @returns The latest message from the user. If not found, returns an empty
 *   string.
 */
export declare function getLatestMessageFromUser(session: Session): string;
export declare const _getLatestMessageFromUser: typeof getLatestMessageFromUser;
/**
 * Builds the few-shot portion of a system instruction from a list of examples
 * or a {@link BaseExampleProvider}.
 *
 * @param examples - Either an array of {@link Example} objects or a
 *   {@link BaseExampleProvider} whose `getExamples` method is called with
 *   `query` to obtain the examples dynamically.
 * @param query - The user query passed to {@link BaseExampleProvider.getExamples}
 *   when `examples` is a provider. Ignored when `examples` is an array.
 * @param model - Optional model name forwarded to
 *   {@link convertExamplesToText} to select the function-call fence style.
 * @returns A promise resolving to a formatted string ready to be appended to a
 *   system instruction.
 * @throws {Error} When `examples` is neither an array nor a
 *   {@link BaseExampleProvider}.
 */
export declare function buildExampleSi(examples: Example[] | BaseExampleProvider, query: string, model?: string): Promise<string>;
